import { fetchAuthSession } from 'aws-amplify/auth';

// Talks to the builtbrush-api HTTP API (API Gateway + Lambda + DynamoDB).
// The server derives the user from the Cognito ID token, so no user id is ever sent.
const API_URL = (process.env.REACT_APP_API_URL || '').replace(/\/$/, '');

const request = async (method, path, body) => {
  if (!API_URL) {
    throw new Error('REACT_APP_API_URL is not set');
  }
  const { tokens } = await fetchAuthSession();
  const idToken = tokens?.idToken?.toString();
  if (!idToken) {
    throw new Error('Not signed in');
  }

  const response = await fetch(`${API_URL}${path}`, {
    method,
    headers: { Authorization: idToken, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined
  });
  if (!response.ok) {
    throw new Error(`API ${method} ${path} failed (${response.status})`);
  }
  if (method !== 'GET') {
    invalidateFetch();
  }
  return response.json();
};

const toLogPayload = (log) => ({ count: log.count, timestamp: log.timestamp });
const toMakeupPayload = (event) => ({
  missedDate: event.missedDate,
  qualifyingDate: event.qualifyingDate,
  restoredAt: event.restoredAt
});

// The API accepts at most 500 operations per request.
const CHUNK = 400;
const chunked = async (items, send) => {
  for (let i = 0; i < items.length; i += CHUNK) {
    await send(items.slice(i, i + CHUNK));
  }
};

// The log sync and makeup sync run back to back and both need /data; share one fetch for a moment.
// Any write invalidates it, so reads after a change are always fresh.
let recentFetch = null;
const invalidateFetch = () => {
  recentFetch = null;
};

export const DataSyncService = {
  async fetchAll() {
    if (!recentFetch) {
      recentFetch = request('GET', '/data').catch((error) => {
        recentFetch = null;
        throw error;
      });
      setTimeout(invalidateFetch, 2000);
    }
    return recentFetch;
  },

  async uploadLog(_userId, log) {
    await request('POST', '/logs', { put: [toLogPayload(log)] });
    return { ...log, id: log.timestamp };
  },

  async uploadLogs(_userId, logs) {
    await chunked(logs, (part) => request('POST', '/logs', { put: part.map(toLogPayload) }));
  },

  // Apply a batch of local edits: upsert `added` (new or changed count), delete `removed` by timestamp.
  async applyLogChanges(added, removed) {
    if (added.length > 0) {
      await this.uploadLogs(null, added);
    }
    await chunked(removed, (part) => request('POST', '/logs', { delete: part.map((log) => log.timestamp) }));
  },

  async deleteLog(logId) {
    await request('POST', '/logs', { delete: [logId] });
  },

  // Merge strategy: cloud is the base, local-only logs are uploaded, never overwritten or dropped.
  async syncData(_userId, localLogs) {
    try {
      const { logs: cloudLogs } = await this.fetchAll();
      const cloudTimestamps = new Set(cloudLogs.map((log) => log.timestamp));
      const localOnly = localLogs.filter((log) => !cloudTimestamps.has(log.timestamp));

      if (localOnly.length > 0) {
        await this.uploadLogs(null, localOnly);
      }

      return [...cloudLogs, ...localOnly.map((log) => ({ ...log, id: log.timestamp }))]
        .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
    } catch (error) {
      console.error('Error syncing data:', error);
      throw error;
    }
  },

  async saveShownAchievements(ids) {
    await request('POST', '/settings', { shownAchievements: ids });
  },

  // Union of local and cloud so a new device never re-shows achievements already seen elsewhere.
  async syncShownAchievements(localIds) {
    const { shownAchievements: cloudIds = [] } = await this.fetchAll();
    const merged = [...new Set([...cloudIds, ...localIds])];
    if (merged.length !== cloudIds.length) {
      await this.saveShownAchievements(merged);
    }
    return merged;
  },

  async uploadMakeupEvent(_userId, event) {
    await request('POST', '/makeup', { put: [toMakeupPayload(event)] });
    return { ...event, id: event.missedDate };
  },

  async deleteMakeupEvent(missedDate) {
    await request('POST', '/makeup', { delete: [missedDate] });
  },

  async syncMakeupEvents(_userId, localEvents) {
    try {
      const { makeupEvents: cloudEvents } = await this.fetchAll();
      const cloudDates = new Set(cloudEvents.map((event) => event.missedDate));
      const localOnly = localEvents.filter((event) => !cloudDates.has(event.missedDate));

      await chunked(localOnly, (part) => request('POST', '/makeup', { put: part.map(toMakeupPayload) }));

      return [...cloudEvents, ...localOnly.map((event) => ({ ...event, id: event.missedDate }))];
    } catch (error) {
      console.error('Error syncing makeup events:', error);
      throw error;
    }
  }
};
