import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL;
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY;

export const isSupabaseConfigured = Boolean(supabaseUrl && supabaseAnonKey);

const supabase = isSupabaseConfigured
  ? createClient(supabaseUrl, supabaseAnonKey)
  : null;

const assertClient = () => {
  if (!supabase) {
    throw new Error('Supabase is not configured. Set REACT_APP_SUPABASE_URL and REACT_APP_SUPABASE_ANON_KEY.');
  }
  return supabase;
};

export const SupabaseSyncService = {
  async getCurrentUser() {
    const client = assertClient();
    const { data, error } = await client.auth.getUser();
    if (error) throw error;
    return data.user || null;
  },

  onAuthStateChange(callback) {
    const client = assertClient();
    const { data } = client.auth.onAuthStateChange((_event, session) => {
      callback(session?.user || null);
    });
    return data.subscription;
  },

  async signUp(email, password) {
    const client = assertClient();
    const { error } = await client.auth.signUp({ email, password });
    if (error) throw error;
  },

  async signIn(email, password) {
    const client = assertClient();
    const { error } = await client.auth.signInWithPassword({ email, password });
    if (error) throw error;
  },

  async signOut() {
    const client = assertClient();
    const { error } = await client.auth.signOut();
    if (error) throw error;
  },

  async uploadLog(userId, log) {
    const client = assertClient();
    const { data, error } = await client
      .from('pushup_logs')
      .insert({
        user_id: userId,
        count: log.count,
        timestamp: log.timestamp
      })
      .select('id, count, timestamp')
      .single();

    if (error) throw error;

    return {
      id: data.id,
      count: data.count,
      timestamp: data.timestamp
    };
  },

  async fetchLogs(userId) {
    const client = assertClient();
    const { data, error } = await client
      .from('pushup_logs')
      .select('id, count, timestamp')
      .eq('user_id', userId)
      .order('timestamp', { ascending: false });

    if (error) throw error;

    return (data || []).map((item) => ({
      id: item.id,
      count: item.count,
      timestamp: item.timestamp
    }));
  },

  async syncData(userId, localLogs) {
    try {
      const cloudLogs = await this.fetchLogs(userId);
      const cloudLogMap = new Map(cloudLogs.map((log) => [log.timestamp, log]));

      const logsToUpload = localLogs.filter((log) => !cloudLogMap.has(log.timestamp));

      if (logsToUpload.length > 0) {
        await Promise.all(logsToUpload.map((log) => this.uploadLog(userId, log)));
      }

      const mergedLogs = [...cloudLogs];
      localLogs.forEach((log) => {
        if (!cloudLogMap.has(log.timestamp)) {
          mergedLogs.push(log);
        }
      });

      mergedLogs.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
      return mergedLogs;
    } catch (error) {
      return localLogs;
    }
  },

  async deleteLog(logId) {
    const client = assertClient();
    const { error } = await client.from('pushup_logs').delete().eq('id', logId);
    if (error) throw error;
  },

  async uploadMakeupEvent(userId, event) {
    const client = assertClient();
    const { data, error } = await client
      .from('makeup_events')
      .insert({
        user_id: userId,
        missed_date: event.missedDate,
        qualifying_date: event.qualifyingDate,
        restored_at: event.restoredAt
      })
      .select('id, missed_date, qualifying_date, restored_at')
      .single();

    if (error) throw error;

    return {
      id: data.id,
      missedDate: data.missed_date,
      qualifyingDate: data.qualifying_date,
      restoredAt: data.restored_at
    };
  },

  async fetchMakeupEvents(userId) {
    const client = assertClient();
    const { data, error } = await client
      .from('makeup_events')
      .select('id, missed_date, qualifying_date, restored_at')
      .eq('user_id', userId)
      .order('missed_date', { ascending: false });

    if (error) throw error;

    return (data || []).map((item) => ({
      id: item.id,
      missedDate: item.missed_date,
      qualifyingDate: item.qualifying_date,
      restoredAt: item.restored_at
    }));
  },

  async syncMakeupEvents(userId, localEvents) {
    try {
      const cloudEvents = await this.fetchMakeupEvents(userId);
      const cloudEventMap = new Map(cloudEvents.map((event) => [event.missedDate, event]));

      const eventsToUpload = localEvents.filter((event) => !cloudEventMap.has(event.missedDate));

      if (eventsToUpload.length > 0) {
        await Promise.all(eventsToUpload.map((event) => this.uploadMakeupEvent(userId, event)));
      }

      const mergedEvents = [...cloudEvents];
      localEvents.forEach((event) => {
        if (!cloudEventMap.has(event.missedDate)) {
          mergedEvents.push(event);
        }
      });

      mergedEvents.sort((a, b) => new Date(b.missedDate) - new Date(a.missedDate));
      return mergedEvents;
    } catch (error) {
      return localEvents;
    }
  },

  async deleteMakeupEvent(eventId) {
    const client = assertClient();
    const { error } = await client.from('makeup_events').delete().eq('id', eventId);
    if (error) throw error;
  }
};
